<?php require 'config.php';$slug=$_GET['slug']??'';$q=db()->prepare('SELECT * FROM features WHERE slug=?');$q->execute([$slug]);$f=$q->fetch();if(!$f){http_response_code(404);exit('Feature not found');}$title=$f['title'].' — FeatureBoard';require 'header.php';$c=db()->prepare('SELECT * FROM comments WHERE feature_id=? ORDER BY created_at DESC');$c->execute([$f['id']]);$comments=$c->fetchAll();$flash=getflash();?>
<section class="page"><div class="wrap detailgrid"><main><div class="panel"><div class="meta"><span class="status <?=e($f['status'])?>"><?=e(ucwords(str_replace('_',' ',$f['status'])))?></span><span class="pill"><?=e($f['category'])?></span></div><h1 style="font-family:'Space Grotesk';font-size:42px;margin-bottom:12px"><?=e($f['title'])?></h1><p style="font-size:17px;line-height:1.7;color:#555"><?=nl2br(e($f['description']))?></p><div class="meta"><span class="pill">Submitted by <?=e($f['author_name'])?></span><span class="pill"><?=date('M j, Y',strtotime($f['created_at']))?></span></div><?php if($f['admin_response']):?><div class="notice" style="margin-top:22px"><b>Team update</b><br><?=nl2br(e($f['admin_response']))?></div><?php endif;?></div><div class="panel" style="margin-top:16px"><h2>Discussion · <?=count($comments)?></h2><div class="comments"><?php foreach($comments as $x):?><div class="comment"><b><?=e($x['name'])?></b> <small><?=date('M j, Y',strtotime($x['created_at']))?></small><p><?=nl2br(e($x['body']))?></p></div><?php endforeach;?><?php if(!$comments):?><p style="color:var(--muted)">Be the first to add context.</p><?php endif;?></div><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><form action="comment.php" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="feature_id" value="<?=$f['id']?>"><div class="field"><label>Add context</label><textarea name="body" rows="4" required placeholder="Why would this help you?"></textarea></div><div class="field"><label>Name</label><input class="input" name="name" required></div><div class="field"><label>Email</label><input class="input" type="email" name="email" required></div><button class="btn">Comment</button></form></div></main><aside><div class="panel"><div class="vote" style="padding:18px"><strong><?=$f['votes']?></strong><span>community votes</span></div><form action="vote.php" method="post" style="margin-top:12px"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="feature_id" value="<?=$f['id']?>"><input class="input" type="email" name="email" required placeholder="your@email.com"><button class="btn orange" style="width:100%;margin-top:8px">▲ Upvote this idea</button></form><p style="font-size:12px;color:var(--muted)">One vote per email for this request.</p></div></aside></div></section><?php require 'footer.php';?>
